+function SolutionPageContent({
+  run,
+  scenarioId,
+}: {
+  run: ActiveRun;
+  scenarioId: number;
+}) {
+  const { activeTabId, setTabUrl } = useRequiredTabContext();
+  const calculationId = run.id;
+  const parentId = run.parent_calculation_id ?? calculationId;
+
+  const { data: recommendationState } = useRecommendationState(
+    { calculationId },
+    { staleTime: Infinity, enabled: isRunOpenable(run.status) },
+  );
+
+  const [isCompareEnabled, setCompareEnabled] = usePersistedState(
+    "isCompareEnabled",
+    false,
+  );
+
+  const openSolution = useMemo(
+    () => ({ calculationId, scenarioId }),
+    [calculationId, scenarioId],
+  );
+  const openSolutionInTab = useCallback(
+    (calculationId: number, scenarioName: string) => {
+      if (!activeTabId) return;
+      setTabUrl(
+        activeTabId,
+        `/ui/new_gantt/recom/${calculationId}/${toScenarioId(scenarioName)}`,
+      );
+    },
+    [activeTabId, setTabUrl],
+  );
+
+  return (
+    <SolutionTreeProvider
+      run={run}
+      parentId={parentId}
+      openSolution={openSolution}
+      isLeftPaneShown={isCompareEnabled}
+      openRunBases={recommendationState?.inputs?.bases}
+      onOpenSolution={openSolutionInTab}
+    >
+      <SolutionPageBody
+        scenarioId={scenarioId}
+        recommendationState={recommendationState}
+        isCompareEnabled={isCompareEnabled}
+        setCompareEnabled={setCompareEnabled}
+      />
+    </SolutionTreeProvider>
+  );
+}
