+import { useCallback, useState } from "react";
+import { Minimize2 } from "lucide-react";
+import { toScenarioName } from "@/apis/recommendation";
+import { Button } from "@/components/ui/button";
+import ScenarioSummaryTable from "@/components/ui/ScenarioSummaryTable";
+import type { ExpandedGroups } from "@/components/ui/CollapsibleTable";
+import {
+  Tooltip,
+  TooltipContent,
+  TooltipTrigger,
+} from "@/components/ui/tooltip";
+import { useSolutionTree } from "@/contexts/SolutionTreeContext";
+import { useViewedSolutions } from "@/hooks/useViewedSolutions";
+import SolutionDecks from "./SolutionDecks";
+import SolutionsPanelHeader from "./SolutionsPanelHeader";
+import { useShownTableRows } from "./useShownTableRows";
+
+type DecksPanelProps = {
+  onCollapse?: () => void;
+};
+
+export default function DecksPanel({ onCollapse }: DecksPanelProps) {
+  const { parentId, openSolution, onOpenSolution } = useSolutionTree();
+  const { isViewed } = useViewedSolutions(parentId);
+  const rows = useShownTableRows();
+  const [showAllSolutions, setShowAllSolutions] = useState(false);
+  const [expandedGroups, setExpandedGroups] = useState<ExpandedGroups>({});
+  const openAndCollapse = (calculationId: number, scenarioName: string) => {
+    onOpenSolution?.(calculationId, scenarioName);
+    onCollapse?.();
+  };
+  const toggleGroup = useCallback(
+    (group: string) =>
+      setExpandedGroups((prev) => ({ ...prev, [group]: !prev[group] })),
+    [],
+  );
+
+  return (
+    <div className="w-full bg-background flex flex-col items-center justify-center">
+      <SolutionsPanelHeader
+        toggle={
+          onCollapse && (
+            <Tooltip>
+              <TooltipTrigger asChild>
+                <Button
+                  variant="ghost"
+                  size="icon"
+                  onClick={onCollapse}
+                  aria-label="Collapse solutions panel"
+                >
+                  <Minimize2 className="size-4" />
+                </Button>
+              </TooltipTrigger>
+              <TooltipContent>Collapse solutions panel</TooltipContent>
+            </Tooltip>
+          )
+        }
+      />
+      <SolutionDecks isViewed={isViewed} onOpenSolution={openAndCollapse} />
+      <Button
+        variant="ghost"
+        className="w-full rounded-none!"
+        onClick={() => setShowAllSolutions((shown) => !shown)}
+      >
+        {showAllSolutions ? "Hide all solutions" : "View all solutions"}
+      </Button>
+      {showAllSolutions && (
+        <ScenarioSummaryTable
+          scenarios={rows}
+          selectedScenario={
+            openSolution && {
+              calculationId: openSolution.calculationId,
+              scenarioName: toScenarioName(openSolution.scenarioId),
+            }
+          }
+          onSelectScenario={openAndCollapse}
+          expandedGroups={expandedGroups}
+          onToggleGroup={toggleGroup}
+          isViewed={isViewed}
+          maxHeight="40vh"
+        />
+      )}
+    </div>
+  );
+}
